const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function getInfo(obj) {
  return await new Promise((resolve, reject) => {
    obj.getInfo((res, err) => {
      if (err) reject(err);
      else resolve(res);
    });
  });
}

function nwPennsylvaniaGeometry() {
  // Approximate NW Pennsylvania bounding box (covers Erie, Crawford, Mercer, Warren, Venango, Forest)
  return ee.Geometry.Rectangle([-80.7, 41.0, -78.4, 42.5], null, false);
}

async function fetchSnowImage(targetDateStr, geom) {
  const datasets = [
    'MODIS/061/MOD10A1', // Terra v61
    'MODIS/061/MYD10A1', // Aqua v61
    'MODIS/006/MOD10A1', // Terra v6
    'MODIS/006/MYD10A1'  // Aqua v6
  ];
  const target = ee.Date(targetDateStr);
  const windows = [
    {start: target, end: target.advance(1, 'day'), label: '±0d'},
    {start: target.advance(-1, 'day'), end: target.advance(2, 'day'), label: '±1d'}
  ];

  for (let w of windows) {
    for (let ds of datasets) {
      const col = ee.ImageCollection(ds)
        .filterBounds(geom)
        .filterDate(w.start, w.end)
        .select('NDSI_Snow_Cover');
      const size = await getInfo(col.size());
      if (size > 0) {
        const img = ee.Image(col.sort('system:time_start').first());
        const usedDate = await getInfo(img.date().format('YYYY-MM-dd'));
        return { image: img, size: size, source: ds, usedDate: usedDate, window: w.label };
      }
    }
  }
  return null;
}

async function computeStats(img, geom) {
  const band = 'NDSI_Snow_Cover';
  const snow = img.select(band);
  const validMask = snow.gte(0).and(snow.lte(100));
  const snowValid = snow.updateMask(validMask);
  const scale = 1000;

  const totalDict = await getInfo(ee.Image(1).reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: geom,
    scale: scale,
    maxPixels: 1e9,
    bestEffort: true
  }));
  const totalCount = (totalDict && totalDict.constant) ? totalDict.constant : 0;

  const validCountDict = await getInfo(snowValid.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: geom,
    scale: scale,
    maxPixels: 1e9,
    bestEffort: true
  }));
  const validCount = (validCountDict && validCountDict[band]) ? validCountDict[band] : 0;

  let meanDict = null;
  let mean = null;
  if (validCount > 0) {
    meanDict = await getInfo(snowValid.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: geom,
      scale: scale,
      maxPixels: 1e9,
      bestEffort: true
    }));
    mean = meanDict ? meanDict[band] : null;
  }

  const cloudInvalidPct = (totalCount > 0)
    ? (100.0 * (totalCount - validCount) / totalCount)
    : null;

  return { totalCount, validCount, cloudInvalidPct, mean };
}

async function runAnalysis() {
  try {
    const geom = nwPennsylvaniaGeometry();

    // Dates of interest
    const dateA = '2020-02-22';
    const dateB = '2020-03-01';

    // Fetch images (with fallbacks)
    const fetchA = await fetchSnowImage(dateA, geom);
    const fetchB = await fetchSnowImage(dateB, geom);

    if (!fetchA || !fetchB) {
      if (!fetchA) console.log(`No images found around ${dateA}.`);
      if (!fetchB) console.log(`No images found around ${dateB}.`);
      console.log('C1');
      return;
    }

    // Compute stats
    const statsA = await computeStats(fetchA.image, geom);
    const statsB = await computeStats(fetchB.image, geom);

    // Validate counts
    if ((statsA.totalCount || 0) === 0 || (statsB.totalCount || 0) === 0) {
      console.log('Total pixels at scale are zero (region/scale issue).');
      console.log('C2');
      return;
    }
    if (statsA.validCount === 0 || statsB.validCount === 0) {
      console.log('No valid pixels after masking.');
      console.log('C2');
      return;
    }

    // Validate means
    const meanA = statsA.mean;
    const meanB = statsB.mean;
    const invalidMean = (v) => (v === null || isNaN(v) || v < 0 || v > 100);
    if (invalidMean(meanA) || invalidMean(meanB)) {
      console.log('Mean snow percent invalid (null/NaN/out of range).');
      console.log('C3');
      return;
    }

    // Print concise evidence
    console.log(`A ${fetchA.usedDate} src:${fetchA.source} imgs:${fetchA.size} totalPix:${statsA.totalCount} validPix:${statsA.validCount} cloud/invalid%:${statsA.cloudInvalidPct.toFixed(1)} meanSnow%:${meanA.toFixed(1)}`);
    console.log(`B ${fetchB.usedDate} src:${fetchB.source} imgs:${fetchB.size} totalPix:${statsB.totalCount} validPix:${statsB.validCount} cloud/invalid%:${statsB.cloudInvalidPct.toFixed(1)} meanSnow%:${meanB.toFixed(1)}`);

    const delta = meanB - meanA;
    console.log(`Delta meanSnow% (B - A): ${delta.toFixed(1)}`);

    // Final answer: Did snow cover increase?
    if (delta > 0) {
      console.log('A');
    } else {
      console.log('B');
    }
  } catch (err) {
    console.error(String(err));
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
